import React from 'react';
import { useState, useEffect, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Row, Col, Label } from 'reactstrap';
import Paper from '@material-ui/core/Paper';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import Checkbox from '@material-ui/core/Checkbox';
import CustomButton from 'components/CustomButton';
import CustomSelect from 'components/CustomSelect';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import { CommonLoader } from 'views/admin/Common/Loader';
import { showToast } from 'actions/admin/auth';
import { fetchBatchCoursesPlainApi } from 'actions/admin/courses';
import { fetchCourseStudentsListApi, moveStudentsCourseApi } from 'actions/admin/students';
import { formStudentName, courseStatic } from 'config/constants';
import { getGlobalSchoolUtils, getGlobalCurrentBatchUtils, formResMessage, toTitleCase } from 'utils/commonFunc';
import colors from 'config/colors';
import { sortCourses } from '../classOrder';

const headStyle = { color: '#7d7d7d', fontSize: 12 };

// Switch class: moves the chosen students from one class to any other class within the selected academic year, for
// example a student who was put in the wrong class. It never changes the academic year - students move up to the next
// year through New academic year. The students are the "from" class's own list, picked with checkboxes.
const SwitchClassPanel = () => {
  const dispatch = useDispatch();
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const { batchId } = getGlobalCurrentBatchUtils();

  const [courses, setCourses] = useState([]);
  const [coursesLoading, setCoursesLoading] = useState(true);
  const [fromId, setFromId] = useState(null);
  const [toId, setToId] = useState(null);
  const [students, setStudents] = useState([]);
  const [studentsLoading, setStudentsLoading] = useState(false);
  const [selectedIds, setSelectedIds] = useState([]);
  const [searchText, setSearchText] = useState('');
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const showWarning = (message, type) => dispatch(showToast(message, type));
  const coursesById = useMemo(() => courses.reduce((acc, c) => ({ ...acc, [c.courseId]: c }), {}), [courses]);
  const fromCourse = coursesById[fromId];
  const toCourse = coursesById[toId];

  useEffect(() => {
    if (!batchId) {
      setCoursesLoading(false);
      return;
    }
    fetchBatchCoursesPlainApi({ batchId, token: loggedUserToken })
      .then(res => setCourses(sortCourses(res.data || [])))
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setCoursesLoading(false));
  }, [batchId]);

  const loadStudents = courseId => {
    setStudentsLoading(true);
    return fetchCourseStudentsListApi({ courseId, batchId, token: loggedUserToken })
      .then(res => setStudents(res.data || []))
      .catch(err => {
        setStudents([]);
        showWarning(formResMessage(err), 'error');
      })
      .finally(() => setStudentsLoading(false));
  };

  const changeFrom = courseId => {
    setFromId(courseId);
    setSelectedIds([]);
    setSearchText('');
    // The destination cannot be the class the students are leaving.
    if (toId === courseId) setToId(null);
    loadStudents(courseId);
  };

  const courseOption = course => ({ value: course.courseId, label: `${course.name} (${course.code})` });
  const fromOptions = courses.map(courseOption);
  const toOptions = courses.filter(course => course.courseId !== fromId).map(courseOption);

  const needle = searchText.trim().toLowerCase();
  const shown = students.filter(
    student =>
      !needle ||
      formStudentName(student).toLowerCase().includes(needle) ||
      `${student.registerNumber || ''}`.toLowerCase().includes(needle)
  );
  const allShownSelected = shown.length > 0 && shown.every(student => selectedIds.includes(student.studentId));

  const toggleStudent = (studentId, checked) =>
    setSelectedIds(prev => (checked ? [...prev, studentId] : prev.filter(id => id !== studentId)));

  const toggleAllShown = checked => {
    const shownIds = shown.map(student => student.studentId);
    setSelectedIds(prev =>
      checked ? [...new Set([...prev, ...shownIds])] : prev.filter(id => !shownIds.includes(id))
    );
  };

  const handleMove = async () => {
    setSaving(true);
    try {
      await moveStudentsCourseApi({
        postData: { schoolId, batchId, fromCourseId: fromId, toCourseId: toId, studentIds: selectedIds },
        token: loggedUserToken,
      });
      showWarning(`${selectedIds.length} student(s) moved to ${toCourse.name}`, 'success');
      setSelectedIds([]);
      await loadStudents(fromId);
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setSaving(false);
    setConfirmOpen(false);
  };

  if (!schoolId || !batchId) {
    return (
      <div style={{ textAlign: 'center', color: '#9a9a9a', padding: 40 }}>
        Please select a school and an academic year first.
      </div>
    );
  }
  if (coursesLoading) return <CommonLoader />;

  const canMove = !!fromId && !!toId && selectedIds.length > 0;

  return (
    <Paper square style={{ padding: 20 }}>
      <Row className="mt-3">
        <Col md={5} sm={12} className="mb-2">
          <Label className="form-label">
            From {courseStatic.toLowerCase()} <sup style={{ color: 'red' }}>*</sup>
          </Label>
          <CustomSelect
            noLabel
            usePortal
            name="fromId"
            value={fromId}
            options={fromOptions}
            onChange={(name, value) => changeFrom(value)}
          />
        </Col>
        <Col md={5} sm={12} className="mb-2">
          <Label className="form-label">
            To {courseStatic.toLowerCase()} <sup style={{ color: 'red' }}>*</sup>
          </Label>
          <CustomSelect
            noLabel
            usePortal
            name="toId"
            value={toId}
            options={toOptions}
            disabled={!fromId}
            placeholder={fromId ? 'Select...' : `Select the "from" ${courseStatic.toLowerCase()} first`}
            onChange={(name, value) => setToId(value)}
          />
          {!!fromId && !toOptions.length && (
            <div style={{ fontSize: 12, color: '#e65100', marginTop: 4 }}>
              There is no other {courseStatic.toLowerCase()} in this academic year to move students to.
            </div>
          )}
        </Col>
      </Row>

      {!!fromId && (
        <div className="mt-3">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 8 }}>
            <span style={{ fontWeight: 'bold', fontSize: 13, color: colors.grey2 }}>
              Students in {fromCourse?.name} ({students.length}) &middot; {selectedIds.length} selected
            </span>
            <input
              className="form-control"
              style={{ height: 34, maxWidth: 260 }}
              placeholder="Search by name or registration number"
              value={searchText}
              onChange={e => setSearchText(e.target.value)}
            />
          </div>
          {studentsLoading ? (
            <CommonLoader />
          ) : students.length ? (
            <div style={{ maxHeight: 380, overflowY: 'auto', border: '1px solid #eee', borderRadius: 6 }}>
              <Table size="small" stickyHeader>
                <TableHead>
                  <TableRow>
                    <TableCell padding="checkbox" style={{ background: colors.white }}>
                      <Checkbox
                        size="small"
                        checked={allShownSelected}
                        indeterminate={!allShownSelected && shown.some(s => selectedIds.includes(s.studentId))}
                        onChange={e => toggleAllShown(e.target.checked)}
                      />
                    </TableCell>
                    <TableCell style={{ ...headStyle, background: colors.white }}>
                      <b>Name</b>
                    </TableCell>
                    <TableCell style={{ ...headStyle, background: colors.white }}>
                      <b>Reg. No</b>
                    </TableCell>
                    <TableCell style={{ ...headStyle, background: colors.white }}>
                      <b>Guardian</b>
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {shown.map(student => (
                    <TableRow key={student.studentId} hover>
                      <TableCell padding="checkbox">
                        <Checkbox
                          size="small"
                          checked={selectedIds.includes(student.studentId)}
                          onChange={e => toggleStudent(student.studentId, e.target.checked)}
                        />
                      </TableCell>
                      <TableCell>{toTitleCase(formStudentName(student))}</TableCell>
                      <TableCell>{student.registerNumber || '--'}</TableCell>
                      <TableCell>{student.guardName || '--'}</TableCell>
                    </TableRow>
                  ))}
                  {!shown.length && (
                    <TableRow>
                      <TableCell colSpan={4} align="center" style={{ color: '#9a9a9a' }}>
                        No students match your search.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          ) : (
            <div style={{ textAlign: 'center', padding: 20, fontSize: 13, color: '#9a9a9a' }}>
              No students in this {courseStatic.toLowerCase()} for the selected academic year.
            </div>
          )}
          <div style={{ textAlign: 'right', marginTop: 12 }}>
            <CustomButton
              name={`Switch ${selectedIds.length ? `${selectedIds.length} student(s)` : 'students'}`}
              disabled={!canMove}
              onClick={() => setConfirmOpen(true)}
              style={canMove ? { backgroundColor: colors.accent, color: colors.white } : undefined}
            />
          </div>
        </div>
      )}

      <ConfirmModal
        size="md"
        confirmModalOpen={confirmOpen}
        confirmMessage={`Move ${selectedIds.length} student(s) from ${fromCourse?.name} to ${toCourse?.name}?`}
        loading={saving}
        deleteConfirm={handleMove}
        deleteCancel={() => setConfirmOpen(false)}
      />
    </Paper>
  );
};

export default SwitchClassPanel;
