// The backend keeps no class order (a course only has a coarse studyLevel: PRIMARY / SECONDARY / ...), so the order of
// the classes in the dropdowns is read off the class name (Nursery, LKG, UKG, 1st, 2nd ...). Classes whose name isn't
// recognised get no rank (null) and are listed last.
const KG_RANKS = [
  { pattern: /\bnursery\b/, rank: -4 },
  { pattern: /\bpre[\s-]*(l?kg|k\.g)\b/, rank: -3 },
  { pattern: /\blkg\b|\bl\.k\.g\b|lower\s*kg/, rank: -2 },
  { pattern: /\bukg\b|\bu\.k\.g\b|upper\s*kg/, rank: -1 },
];

export const classRank = name => {
  const text = `${name || ''}`.toLowerCase();
  const kg = KG_RANKS.find(entry => entry.pattern.test(text));
  if (kg) return kg.rank;
  const standard =
    text.match(/(\d{1,2})\s*(?:st|nd|rd|th)\b/) || text.match(/(?:class|grade|std|standard)\s*(\d{1,2})\b/);
  return standard ? Number(standard[1]) : null;
};

// Course order for the dropdowns: by rank (lowest class first), unranked ones last, then by name.
export const sortCourses = courses =>
  [...courses].sort((a, b) => {
    const ra = classRank(a.name);
    const rb = classRank(b.name);
    if (ra !== rb) return (ra ?? Infinity) - (rb ?? Infinity);
    return `${a.name}`.localeCompare(`${b.name}`);
  });
